<?php
namespace App\Services;use App\Models\PricingVersion;
class QuotationCalculator{public function calculate(array $answers,PricingVersion $pricing):array{$r=$pricing->rules;$quantity=(int)$answers['vacancies'];$base=(int)$r['base']*$quantity;$publication=(int)round($base*$r['duration'][(string)$answers['duration']]*$r['applications'][$answers['applications']]*$r['urgency'][$answers['urgency']]);$extras=((int)$r['visibility'][$answers['visibility']]+(int)$r['classification'][$answers['classification']]+collect($answers['diffusion'])->sum(fn($item)=>(int)$r['diffusion'][$item]))*$quantity;$subtotal=$publication+$extras;$discountRate=collect($r['volume_discounts'])->filter(fn($rate,$minimum)=>$quantity>=(int)$minimum)->last()??0;$discount=(int)round($subtotal*$discountRate);$taxable=$subtotal-$discount;$tax=(int)round($taxable*$r['tax_rate']);return ['breakdown'=>['publication'=>$publication,'extras'=>$extras,'volume_discount_rate'=>$discountRate,'tax_rate'=>$r['tax_rate']],'subtotal'=>$subtotal,'discount'=>$discount,'tax'=>$tax,'total'=>$taxable+$tax];}}
